function renderTopRight(settings){const topRightOrder=settings.topRightOrder||[];let container=document.getElementById("top-right");if(!container)return;container.innerHTML="";const sidebarHasHistory=Boolean(settings.sidebar&&(settings.sidebarWidgets||[]).includes("history"));topRightOrder.forEach((item)=>{if(item.displayBool){if(item.id==="history"&&sidebarHasHistory){return;}
let itemElem=document.createElement("span");itemElem.id="open-"+item["id"];itemElem.innerHTML=item["id"];itemElem.addEventListener('click',()=>{chrome.tabs.create({url:item['url']});});container.append(itemElem);}});}
export{renderTopRight};